def make(n):
    base = 2000
    return [[str(base + i)] for i in range(n)]

def make(n):
    base_year = 2000
    return [[f"{base_year + i:04d}-01"] for i in range(n)]

def make(n):
    # Return n calls each with the string "present"
    return [["present"] for _ in range(n)]
